SELECT COUNT(*) AS brand_new_count
FROM nlq.listings
WHERE condition ILIKE '%new%';

SELECT COUNT(*) AS total_listings_at_iv
FROM nlq.listings
WHERE meetup_spot = 'International Village';

SELECT MAX(rent_price_per_week) AS highest_weekly_rent
FROM nlq.listings
WHERE rent_price_per_week IS NOT NULL;

SELECT COUNT(*) AS small_blazer_count
FROM nlq.listings
WHERE (title ILIKE '%small blazer%' OR description ILIKE '%small blazer%');

SELECT COUNT(*) AS monitor_count
FROM nlq.listings
WHERE (title ILIKE '%27%monitor%' OR description ILIKE '%27%monitor%');

SELECT ROUND(100.0 * SUM(CASE WHEN rent_price_per_week IS NOT NULL THEN 1 ELSE 0 END) / COUNT(*), 2) AS rent_percentage
FROM nlq.listings
WHERE category = 'electronics';

SELECT round(percentile_cont(0.5) WITHIN GROUP (ORDER BY rent_price_per_week)::numeric, 2) AS median_weekly_rent
FROM nlq.listings
WHERE rent_price_per_week IS NOT NULL;

SELECT COUNT(*) AS pickup_only_listings
FROM nlq.listings
WHERE (title ILIKE '%pickup only%' OR description ILIKE '%pickup only%');

SELECT COUNT(*) AS listings_posted_since_oct_1
FROM nlq.listings
WHERE (listed_at AT TIME ZONE 'America/New_York')::date >= DATE '2026-10-01';

SELECT COUNT(*) AS five_star_ratings
FROM nlq.my_reviews
WHERE direction = 'received' AND rating = 5;

SELECT COUNT(*) AS listings_removed
FROM nlq.my_listings
WHERE status = 'removed';

SELECT COUNT(*) AS reviews_under_4_stars
FROM nlq.my_reviews
WHERE direction = 'received' AND rating < 4;

SELECT COUNT(DISTINCT category) AS category_count
FROM nlq.my_deals
WHERE my_role = 'buyer' AND deal_type = 'sale' AND status = 'completed';

select coalesce(sum(case when my_role = 'seller' then agreed_price else -agreed_price end), 0) as net_earned
from nlq.my_deals
where status = 'completed';

SELECT COUNT(*) AS total_requested_deals
FROM nlq.deals
WHERE status = 'requested';

SELECT ROUND(100.0 * SUM(CASE WHEN status = 'cancelled' THEN 1 ELSE 0 END) / COUNT(*)::numeric, 2) AS cancelled_percent
FROM nlq.deals
WHERE deal_type = 'sale';

SELECT COUNT(*) AS reserved_listings
FROM nlq.listings_all
WHERE status = 'reserved';

SELECT COUNT(*) AS like_new_count
FROM nlq.listings_all
WHERE condition ILIKE 'like_new';

SELECT COUNT(*) AS suspended_accounts
FROM nlq.students
WHERE account_status = 'suspended';

SELECT COUNT(*) AS resolved_report_count
FROM nlq.reports
WHERE status = 'resolved';

SELECT COUNT(*) AS listings_with_four_photos
FROM nlq.listings_all
WHERE photo_count = 4;

SELECT COUNT(*) AS total_1_star_reviews
FROM nlq.reviews
WHERE rating = 1;

SELECT COUNT(*) AS reports_against_listings
FROM nlq.reports
WHERE target_type = 'listing';

select count(*) as rented_out_items
from nlq.listings_all
where status = 'rented_out';

SELECT name
FROM nlq.meetup_spots
WHERE area = 'off campus';

SELECT category, label
FROM nlq.categories
WHERE category_group = 'leisure';

SELECT round(avg(buyer_message_count)::numeric, 2) AS avg_buyer_messages,
       round(avg(seller_message_count)::numeric, 2) AS avg_seller_messages
FROM nlq.conversations;

SELECT COUNT(*) AS buyer_more_messages_conversations
FROM nlq.conversations
WHERE buyer_message_count > seller_message_count;

SELECT COUNT(*) AS deposit_report_count
FROM nlq.reports
WHERE reason ILIKE '%deposit%' OR reason ILIKE '%down%';

SELECT COUNT(*) AS students_never_posted
FROM nlq.students s
WHERE NOT EXISTS (
    SELECT 1 FROM nlq.listings_all la WHERE la.seller_id = s.student_id
);

SELECT ROUND(100.0 * SUM(CASE WHEN status = 'removed' THEN 1 ELSE 0 END) / COUNT(*), 2) AS pct_removed
FROM nlq.listings_all
WHERE condition = 'good';

SELECT round(100.0 * SUM(CASE WHEN resolved_at - filed_at <= INTERVAL '48 hours' THEN 1 ELSE 0 END) / COUNT(*), 2) AS pct_closed_within_48h
FROM nlq.reports
WHERE status = 'resolved';

SELECT ROUND(100.0 * AVG(CASE WHEN r.rating >= 4.5 THEN 1 ELSE 0 END), 2) AS pct_avg_4_5_or_better
FROM nlq.reviews r
WHERE r.reviewer_role = 'buyer';

select count(*) as students_posted_no_sale
from (
  select distinct seller_id
  from nlq.listings_all
) sub
where not exists (
  select 1 from nlq.deals d
  where d.seller_id = sub.seller_id
    and d.deal_type = 'sale'
    and d.status = 'completed'
);

select count(*) as listings_saved_by_5_or_more_never_sold
from (
  select s.item_id,
         count(distinct s.student_id) as student_cnt
  from nlq.saved_items s
  group by s.item_id
) sub
where student_cnt >= 5
  and not exists (
    select 1 from nlq.deals d where d.item_id = sub.item_id and d.deal_type = 'sale' and d.status = 'completed'
  );
